import {section,table,cite,topic,mountTopic} from './topic-tools.js';
import {texEq as eq} from './math.js';
import {samplingDistribution,guidedLogits} from './decoding-model.js';
import {entropy} from './information-model.js';
export const decodingSections=[['distribution','The model is not the sampler'],['temperature','Temperature changes relative preference'],['support','Top-k and nucleus sampling'],['sampling-lab','Inspect the transformed distribution'],['guidance','LoopCD: extrapolate recurrent refinement'],['watermark','Watermark the token choices'],['tournament','Tournament generation and detection'],['non-distortion','What non-distortion actually means'],['evidence','Entropy, editing and evidence'],['deployment','Dated deployment context'],['implementation','Sampler implementation contract'],['sources','Sources and connected notes']];
export const decodingMeta={slug:'execution/decoding',title:'Decoding and Sampling',description:'Temperature, support truncation, recurrent-state guidance and keyed watermark sampling change how model predictions become tokens.',date:'2026-05-29',updated:'2026-10-06',topicPath:['execution'],tags:['decoding','sampling','temperature','top-k','top-p','nucleus','LoopCD','SynthID','watermark'],prototype:true,visibility:'public',kind:'dense-topic',learningGoals:['Distinguish distribution sharpness, support and guidance','Implement an explicit transformation order','Interpret watermark detection and non-distortion with the correct scope'],related:['execution/speculation','math/information','training/objectives']};
export const decodingAliases=[];
export function samplerPresentation(options={}){
 const probabilities=samplingDistribution([4,2,1,0],options);
 return {probabilities,entropy:entropy(probabilities).toFixed(3),support:probabilities.filter(v=>v>0).length,rows:probabilities.map((v,i)=>`<div class="probability-row"><span>${'ABCD'[i]}</span><div class="probability-track" aria-hidden="true"><i style="width:${v*100}%"></i></div><span class="probability-value">${v.toFixed(3)}</span></div>`).join('')};
}
const initialSampler=samplerPresentation();
const samplerLab=`<div id="sampling-lab" class="topic-scene" data-sampler-lab><h3>Same logits. Different sampler.</h3><p>Four synthetic logits: [4, 2, 1, 0]. Order: temperature → top-k → nucleus → renormalize.</p><label>Temperature <output data-temp>1.0</output><input type="range" min="0.1" max="2" step="0.1" value="1" aria-label="Sampling temperature"></label><label>Top-k <select aria-label="Top-k cutoff"><option value="0">Disabled</option><option value="1">1</option><option value="2">2</option><option value="3">3</option></select></label><label>Nucleus threshold <select aria-label="Top-p cutoff"><option value="1">Disabled</option><option value="0.9">0.9</option><option value="0.7">0.7</option></select></label><div class="probability-rows" data-probability-rows aria-label="Transformed token probabilities">${initialSampler.rows}</div><div class="scene-stats"><span>Entropy <output data-entropy>${initialSampler.entropy}</output> bits</span><span>Eligible tokens <output data-support>${initialSampler.support}</output></span></div><p class="topic-scenes-caption">Temperature does not add knowledge or verify factual correctness. Truncation creates exact zeros.</p></div>`;
const guideLab=`<div class="topic-scene" data-guidance-lab><h3>Continue a change in preference</h3><p>Reference logits [2,1]. Final logits [2.1,2]. Refinement increased B more than A.</p><label>Guidance strength <output data-strength>0.5</output><input type="range" min="0" max="1" step="0.05" value="0.5" aria-label="LoopCD guidance strength"></label><div class="scene-stats"><span>Guided A <output data-ga>2.15</output></span><span>Guided B <output data-gb>2.50</output></span><span>Greedy choice <output data-choice>B</output></span></div><p data-guide-caption>This illustrates a ranking change, not evidence that B is correct.</p></div>`;
export function decodingReader(link){return topic(decodingMeta,decodingSections,'Logits express a preference. The decoder decides how that preference becomes a token.',`
<p>Inference-time decoding controls do not retrain the model. They modify the distribution or decision used to emit tokens. Temperature changes relative preference. Truncation changes eligibility. Guidance changes the scores themselves. A watermark creates a keyed statistical correlation in token selection.</p><p>These mechanisms solve different problems. They should not be treated as interchangeable “creativity settings.” Speculative decoding then accelerates a specified target sampler; it must account for the actual probabilities after these transformations.</p>
${section('distribution','The model is not the sampler',`<p>A vocabulary head produces logits z₁…zᵥ. Softmax converts them to positive probabilities. The next-token sampler can transform those scores before selecting an outcome.</p>${eq(String.raw`p_i=\frac{\exp(z_i-m)}{\sum_j\exp(z_j-m)},\qquad m=\max_jz_j`,'Subtracting the maximum leaves softmax unchanged and avoids overflow. Masks can set banned-token logits to −∞; an all-banned row needs an explicit error policy.')}
<p>Greedy decoding chooses a maximum-logit token. Sampling chooses according to a distribution. Deterministic tie-breaking, seed management and floating-point kernels affect reproducibility. An identical RNG seed does not guarantee identical text across changed implementations.</p>`)}
${section('temperature','Temperature changes relative preference',`${eq(String.raw`p_i(T)=\operatorname{softmax}(z/T)_i,\qquad\frac{p_i(T)}{p_j(T)}=\exp\!\left(\frac{z_i-z_j}T\right)`,'T must be positive for this formula. Temperature zero is usually implemented as a separate greedy branch.')}
<p>T below one amplifies logit differences. T above one compresses them. Finite positive temperature preserves ranking and support before numerical rounding. It changes how much probability the leading tokens receive.</p><p>For logits 10 and 8, the ratio is exp(4) at T=0.5 and exp(1) at T=2. Lowering T does not tell the model which answer is true. It can make a confident error more likely.</p><p>As T approaches zero, probability concentrates on maximizers. If several logits tie, the mathematical limit shares mass across them. A deterministic greedy implementation may choose only one. State the tie policy.</p>`)}
${section('support','Top-k and nucleus sampling',`<p>Top-k keeps a fixed number of highest-scoring tokens, zeros the rest and renormalizes. It changes support rather than only sharpness. k=1 gives greedy selection under a stated tie rule.</p>${eq(String.raw`p'_i=\begin{cases}\displaystyle\frac{p_i}{\sum_{j\in S_k}p_j}&i\in S_k\\0&i\notin S_k\end{cases}`,'Sₖ is the chosen top-k set. If a threshold implementation retains ties at the boundary, it may keep more than k tokens.')}
<p>For example, let the=0.30, a=0.20 and this=0.12 be the leading three token probabilities. Their total is 0.62, so top-3 probabilities become about 0.484, 0.323 and 0.194. These three values do not describe the complete vocabulary; assume every remaining token is below the cutoff.</p><p>Top-p, or nucleus sampling, sorts probabilities and keeps the smallest prefix whose cumulative mass reaches the threshold. Include the token that crosses the threshold. A confident distribution can keep one token; a broad one can keep many.</p><p>Transformation order matters. Temperature changes which nucleus meets a given probability mass. Combining top-k and top-p can mean applying nucleus to the already-renormalized top-k distribution, as in the example below. Other engines use different orders.</p>${samplerLab}<p>Common starting ranges—roughly 0–0.3 for focused tasks, 0.5–0.8 for general chat, 0.9–1.2 for creative text, and top-k around 10 or 40–50—are only starting heuristics. They are not portable recommendations for every model. Validate quality, failure rates and diversity on your workload.</p>`)}
${section('guidance','LoopCD: extrapolate recurrent refinement',`<p>A looped transformer processes a prefix repeatedly with shared weights. The paper evaluates Ouro, Huginn, Parcae and Looped-Qwen3. An earlier completed loop and the final loop give two states for the same next-token decision. LoopCD extrapolates from the reference toward the final state and beyond.</p>${eq(String.raw`\begin{aligned}\text{Logit guidance:}\quad z'&=z_{\rm final}+w(z_{\rm final}-z_{\rm ref})\\\text{Hidden guidance:}\quad h'&=h_{\rm final}+w(h_{\rm final}-h_{\rm ref})\end{aligned}`,'Decode h′ through the normal final normalization/coda/output head. Logit guidance decodes both states, so it needs an extra output pass.')}${guideLab}<p>A linear output map makes hidden and logit extrapolation commute. Actual output paths include normalization and sometimes nonlinear coda layers. The two variants can therefore change rankings differently.</p>${eq(String.raw`w=w_{\max}\left[1-(p_{\rm top1}-p_{\rm top2})\right]`,"Probabilities come from the unguided final logits; w_max≥0.")}<p>The adaptive logit rule uses the gap between the two leading probabilities. A small probability margin receives stronger guidance. Applying this exact rule to hidden guidance can require an extra output pass to obtain those probabilities, losing its principal cost advantage.</p><p>The source reports Ouro-2.6B-Thinking AIME 2024 pass@1 improving from 61.88% to 73.33% with logit guidance, and Huginn HumanEval from 22.56% to 31.71% with hidden guidance. Half-depth experiments report 22.5–48.2% fewer forward FLOPs on a multiple-choice suite while recovering baseline quality. The arithmetic estimate uses a 512-token prefill; it is not a measured serving speedup.</p><p>Choose strength on held-out data, then lock it before final evaluation. Compare unguided full-depth, guided full-depth and shorter guided runs. Keep checkpoint, prompt and sampler fixed. Start with w=0 to recover the baseline. Capture complete loop boundaries, align the coda interface, and preserve reference/final tensors without in-place edits or buffer reuse. Huginn’s noisy initialization needs a later reference after burn-in. A second coda branch must not overwrite the final branch’s KV state.</p><p>Excessive guidance amplifies errors. Measure generated token counts as well as loop counts: longer reasoning can erase the savings. Track peak memory, prefill time, time per generated token and throughput at realistic batches. Inspect repeated-token failures and temperature sensitivity. Transferring this update to a recurrent vision backbone is a hypothesis, not an established result.</p><p>${cite('https://arxiv.org/abs/2610.02185','LoopCD paper')} · <a href="${link('models/recurrence')}">Ouro reference →</a></p>`)}
${section('watermark','Watermark the token choices',`<p>A text watermark is not metadata, hidden Unicode or a writing style. It is a deliberate statistical relationship between emitted tokens and a secret key. Copying the words preserves it; replacing the words can remove it.</p><p>SynthID-Text adds keyed sampling after ordinary distribution transformations. It requires no extra output tokens or model retraining. A detector reconstructs local keyed scores from a passage without needing the prompt or rerunning the LLM.</p>${eq(String.raw`\begin{aligned}\text{logits}&\to\text{temperature / truncation}\to\text{keyed sampling}\to x_t\\r_t&=\operatorname{hash}(x_{t-H:t-1},\text{key}),\qquad H=4\end{aligned}`,'The main paper configuration uses a four-token context. The same token can receive unrelated scores after different contexts.')}
<p>This differs from a post-hoc AI detector. A post-hoc detector infers origin from naturally occurring patterns. A watermark deliberately creates a testable correlation.</p>`)}
${section('tournament','Tournament generation and detection',`<p>Conceptually, m binary tournament layers begin with 2<sup>m</sup> independent samples from the model distribution. Candidate tokens can repeat. In each layer, pair candidates and select the higher keyed score under that layer’s function. Random tie-breaking handles identical scores.</p><div class="dense-flow" role="img" aria-label="Eight sampled candidates become four winners, then two, then one"><div>8 candidates</div><span>→</span><div>4 winners<br><small>keyed function g₁</small></div><span>→</span><div>2 winners<br><small>g₂</small></div><span>→</span><div>1 token<br><small>g₃</small></div></div><p>This is the conceptual construction, not a requirement to materialize exponentially many candidates in production. The paper provides more efficient vectorized sampling.</p>${eq(String.raw`S(x_{1:T})=\frac1{mT'}\sum_{t\in\mathcal I}\sum_{\ell=1}^m g_\ell(x_t,r_t)`,"Illustrative mean detector score: m≥1 layers, usable positions I, T′=|I|>0. This is not a calibrated probability of authorship.")}<p>The detector uses the expected tokenizer and key, reconstructs recent contexts, recomputes emitted-token scores and aggregates usable positions. The mean score above averages keyed values over usable positions and layers. Unwatermarked text supplies a random-score baseline; tournament winners tend to score higher. Weighted, frequentist and learned Bayesian scores can use the evidence differently.</p><p>A secret ordinary RNG seed alone does not provide this detector. Replaying an ordinary sampler would require the original prompt and model probabilities. Tournament scores can be reconstructed from the observed tokens themselves.</p>`)}
${section('non-distortion','What non-distortion actually means',`<p>The two-competitor tournament has a single-token distribution-preservation guarantee averaged over the random keyed seed. This is not equality conditional on a fixed known seed or key. A particular keyed ranking deliberately favors some candidates.</p><p>Sequence-level guarantees are stronger than a marginal token guarantee. Repeated-context masking prevents repeatedly reusing the same random ranking in a way that accumulates distortion. The paper’s configurations distinguish single-sequence and multiple-sequence preservation.</p><p>More than two competitors per match can strengthen detection while distorting token probabilities. Stronger preservation can reduce detectability or diversity advantages. “Non-distortionary” therefore needs its averaging conditions and configuration, not an unqualified claim of identical text.</p>`)}
${section('evidence','Entropy, editing and evidence',`<p>A nearly deterministic next-token distribution offers almost no watermark choice. Most tournament candidates are the same token. A broad distribution offers alternatives, so the key can influence which plausible token wins.</p><p>Long unchanged prose often supplies more evidence than short answers, rigid factual strings or low-entropy code. Text length alone is insufficient: many repeated or deterministic positions add little useful signal.</p><p>Changing one token replaces its score and changes the seeds for following positions in the context window. Minor edits can leave enough evidence. Paraphrasing, translation, heavy rewriting and fragment mixing weaken it. Semantic preservation is not token preservation.</p><p>A detection threshold trades false positives against missed watermarks. Calibration and abstention matter. A positive result supports consistency with a supported keyed generation process; it does not prove that the model invented the ideas or wrote every word.</p><p>A negative result is not proof of human authorship. The scheme does not identify a particular user, account or conversation. Keep provider attribution separate from personal attribution.</p><p>The key is a security boundary. Key exposure can enable forgery or scrubbing attempts. Detection APIs, rate limits, key rotation and key management can help, but watermarks do not solve universal AI detection. Provider participation is voluntary; open-weight deployments need not include compatible watermarking. Signed provenance, platform records and contextual evidence remain complementary.</p>`)}
${section('deployment','Dated deployment context',`<p>Anthropic’s August 2026 announcement describes a SynthID-based text watermark rollout for models released on or after August 2, with earlier-model support described separately. This is a dated announcement, not proof that every historical Claude response contains a detectable watermark.</p><p>File provenance uses a different mechanism, such as signed C2PA metadata. A statistical token watermark and signed file credentials should not be treated as interchangeable.</p><p>${cite('https://www.anthropic.com/news/claude-text-watermark','Original Anthropic announcement')} gives the dated deployment details. Verify current model support and detection availability before relying on a specific service.</p>`)}
${section('implementation','Sampler implementation contract',`<ol class="dense-checklist"><li>Specify logits, dtype, temperature and transformation order.</li><li>Specify banned-token, repetition and EOS policies.</li><li>Define top-k ties, the nucleus crossing token and all-masked behavior.</li><li>Normalize the final support before sampling.</li><li>Record the actual proposal probabilities when speculative decoding needs them.</li><li>Distinguish reproducibility from distributional equivalence.</li><li>Evaluate accuracy, output length, repetition, diversity and throughput under the same settings.</li></ol><p>For a watermark, also specify tokenizer, context length, repetition masking, key configuration and detector calibration. A toy tournament diagram is not a cryptographic implementation.</p><p><a href="${link('execution/speculation')}">Speculative Decoding →</a> preserves a specified target distribution; LoopCD deliberately changes one. This distinction prevents calling every inference-time improvement “lossless.”</p>`)}
${section('sources','Sources and connected notes',`<p>${cite('https://arxiv.org/abs/1904.09751','Nucleus sampling')} · ${cite('https://www.nature.com/articles/s41586-024-08025-4','SynthID-Text paper')} · ${cite('https://deepmind.google/blog/watermarking-ai-generated-text-and-video-with-synthid/','DeepMind explanation')}</p><div class="dense-related"><a href="${link('execution/speculation')}">Speculative Decoding →</a><a href="${link('math/information')}">Information Theory →</a><a href="${link('models/recurrence')}">Recurrent Models →</a><a href="${link('post-training/reasoning')}">Reasoning Compute →</a><a href="${link('execution/serving')}">Serving →</a><a href="${link('execution/performance')}">Performance →</a></div>`)}
`);}
decodingMeta.searchText=decodingReader(()=> '').replace(/<[^>]*>/g,' ');
export function mountDecoding(scope=document){mountTopic(scope,decodingMeta.slug,article=>{const lab=article.querySelector('[data-sampler-lab]'),temp=lab.querySelector('input'),k=lab.querySelector('[aria-label="Top-k cutoff"]'),p=lab.querySelector('[aria-label="Top-p cutoff"]');const draw=()=>{const f=samplerPresentation({temperature:Number(temp.value),topK:Number(k.value),topP:Number(p.value)});lab.querySelector('[data-temp]').textContent=Number(temp.value).toFixed(1);lab.querySelector('[data-entropy]').textContent=f.entropy;lab.querySelector('[data-support]').textContent=f.support;lab.querySelector('[data-probability-rows]').innerHTML=f.rows;};for(const input of [temp,k,p])input.addEventListener('input',draw);draw();const guide=article.querySelector('[data-guidance-lab]'),slider=guide.querySelector('input');const update=()=>{const strength=Number(slider.value),z=guidedLogits([2.1,2],[2,1],strength);guide.querySelector('[data-strength]').textContent=strength.toFixed(2);guide.querySelector('[data-ga]').textContent=z[0].toFixed(2);guide.querySelector('[data-gb]').textContent=z[1].toFixed(2);guide.querySelector('[data-choice]').textContent=z[0]>=z[1]?'A':'B';};slider.addEventListener('input',update);update();});}
